/*
 * A138553  Table read by rows: T(n,k) is the number of divisors of k that are
 *          <= n.
 * https://oeis.org/A138553
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn, tabf
 * Formula:   this function implements the OEIS sequence A138553. The sequence
 *            is generated by reading the infinite table T(n,k) row‑by‑row,
 *            where T(n,k) = number of divisors of k that are <= n. Each row n
 *            repeats after LCM(1,2,…,n) entries. The function computes a(n)
 *            (1‑based index) without storing the whole...
 * Range:     u8 n <= 105, u16 n <= 105, u32 n <= 105, u64 n <= 105,
 *            u128 n <= 105, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>

/* Auxiliary: 64‑bit gcd */
static uint64_t gcd_uint64(uint64_t a, uint64_t b) {
    while (b != 0) {
        uint64_t t = a % b;
        a = b;
        b = t;
    }
    return a;
}

/* Main sequence function */
seq_t a(idx_t n) {
    /* Step 1: find the row r that contains the n‑th term */
    uint64_t row = 1;                 /* current row number (1‑based)   */
    uint64_t L = 1;                   /* period LCM(1..row) for current row */
    __uint128_t cumulative = 0;       /* sum of periods of previous rows  */

    /* Find r such that cumulative + L >= n */
    while (1) {
        __uint128_t next_cum = cumulative + ( __uint128_t )L;
        if (next_cum >= ( __uint128_t )n)
            break;                    /* term lies in current row */

        cumulative = next_cum;        /* move to next row */
        ++row;                        /* advance row number */

        /* update L = lcm(L, row) safely using 128‑bit arithmetic */
        uint64_t g = gcd_uint64(L, row);
        __uint128_t prod = ( __uint128_t )(L / g) * row;
        if (prod > ( __uint128_t )UINT64_MAX)
            L = UINT64_MAX;           /* cap to avoid overflow */
        else
            L = (uint64_t)prod;
    }

    /* Step 2: compute the offset of the required term within this row */
    idx_t offset = (idx_t)( ( __uint128_t )n - cumulative );  /* 1‑based within row */

    /* Step 3: count divisors of offset that are <= row */
    seq_t count = 0;
    uint64_t k = (uint64_t)offset;    /* offset fits in 64‑bit for all practical n */
    for (uint64_t d = 1; d * d <= k; ++d) {
        if (k % d == 0) {
            if (d <= row) count++;
            uint64_t d2 = k / d;
            if (d2 != d && d2 <= row) count++;
        }
    }

    return count;
}
